58	// ── Helper: distance calculation (Haversine-like) ───────────────────────────
59	
60	const calculateDistance = (
61	  lat1: number,
62	  lon1: number,
63	  lat2: number,
64	  lon2: number,
65	): number => {
66	  const R = 6371;
67	  const dLat = ((lat2 - lat1) * Math.PI) / 180;
68	  const dLon = ((lon2 - lon1) * Math.PI) / 180;
69	  const a =
70	    Math.sin(dLat / 2) ** 2 +
71	    Math.cos((lat1 * Math.PI) / 180) *
72	    Math.cos((lat2 * Math.PI) / 180) *
73	    Math.sin(dLon / 2) ** 2;
74	  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
75	};
76	
77	describe('LogisticsAnalyticsDashboard — distance helper', () => {
78	  it('returns 0 when same coordinates', () => {
79	    const d = calculateDistance(-15.8, -47.9, -15.8, -47.9);
80	    expect(d).toBeCloseTo(0, 1);
81	  });
82	
83	  it('returns positive distance between two different points', () => {
84	    const d = calculateDistance(-15.8, -47.9, -16.0, -48.0);
85	    expect(d).toBeGreaterThan(0);
86	  });
87	});
