236	// startOfWeek: returns the Monday of the current week
237	function startOfWeek(date = new Date()) {
238	    const d = new Date(date);
239	    const day = d.getDay();
240	    const diff = (day === 0 ? -6 : 1) - day;
241	    d.setDate(d.getDate() + diff);
242	    d.setHours(0, 0, 0, 0);
243	    return d;
244	}
