246	// formatDateISO: returns YYYY-MM-DD from a Date (local time)
247	function formatDateISO(d: Date) {
248	    const y = d.getFullYear();
249	    const m = String(d.getMonth() + 1).padStart(2, '0');
250	    const day = String(d.getDate()).padStart(2, '0');
251	    return `${y}-${m}-${day}`;
252	}
