266	const toMinutes = (t?: string | null): number => {
267	    if (!t) return Number.POSITIVE_INFINITY;
268	    const parts = String(t).split(':');
269	    const h = Number(parts[0] || 0);
270	    const m = Number(parts[1] || 0);
271	    return h * 60 + m;
