517	const RECORRENCIA_SEMANAL_OCORRENCIAS = 12;
518	const RECORRENCIA_MENSAL_OCORRENCIAS = 12;
519	function gerarDatasRecorrencia(
520	  baseISO: string,
521	  tipo: 'semanal' | 'mensal',
522	): string[] {
523	  const base = parseISODateLocal(baseISO);
524	  const datas: string[] = [];
525	  if (tipo === 'semanal') {
526	    for (let i = 1; i <= RECORRENCIA_SEMANAL_OCORRENCIAS; i++) {
527	      const d = new Date(base);
528	      d.setDate(base.getDate() + i * 7);
529	      datas.push(formatDateISO(d));
530	    }
531	  } else {
532	    const baseDay = base.getDate();
533	    for (let i = 1; i <= RECORRENCIA_MENSAL_OCORRENCIAS; i++) {
534	      const d = new Date(base.getFullYear(), base.getMonth() + i, 1);
535	      const lastDayOfMonth = new Date(
536	        d.getFullYear(),
537	        d.getMonth() + 1,
538	        0,
539	      ).getDate();
540	      d.setDate(Math.min(baseDay, lastDayOfMonth));
541	      datas.push(formatDateISO(d));
542	    }
543	  }
544	  return datas;
545	}
