95	function expandRecurringItems(
96	  items: { data_inicio: string; recorrencia?: string; status?: string }[],
97	  weekStart: Date,
98	  weekEnd: Date,
99	) {
100	  const result: any[] = [];
101	  for (const item of items) {
102	    if (!item.recorrencia || item.recorrencia === 'unica') {
103	      result.push(item);
104	      continue;
