/**
 * Módulo de tracing — helpers para criar spans OpenTelemetry.
 *
 * withTrace() para funções assíncronas e withTraceSync() para síncronas.
 * Quando desabilitado, simplesmente executa a função sem overhead.
 *
 * Uso:
 *   import { withTrace } from '@/shared/lib/telemetry/tracer';
 *   const result = await withTrace('auth.signIn', async (span) => { ... });
 */

import type { Span, Tracer } from '@opentelemetry/api';
import { isInitialized, getTelemetryConfig } from './telemetry';

// ---------------------------------------------------------------------------
// Estado do módulo
// ---------------------------------------------------------------------------

let _tracer: Tracer | null = null;

async function getTracer(): Promise<Tracer | null> {
  if (_tracer) return _tracer;
  if (!isInitialized() || !getTelemetryConfig().enabled) return null;

  const { trace } = await import('@opentelemetry/api');
  const config = getTelemetryConfig();
  _tracer = trace.getTracer(config.serviceName, config.serviceVersion);
  return _tracer;
}

