138	function startOfWeek(date = new Date()) {
139	  const d = new Date(date);
140	  const day = d.getDay();
141	  const diff = (day === 0 ? -6 : 1) - day;
142	  d.setDate(d.getDate() + diff);
143	  d.setHours(0, 0, 0, 0);
144	  return d;
145	}
146	
147	function formatDateISO(d: Date) {
148	  const y = d.getFullYear();
149	  const m = String(d.getMonth() + 1).padStart(2, '0');
150	  const day = String(d.getDate()).padStart(2, '0');
151	  return `${y}-${m}-${day}`;
152	}
153	
154	function parseISODateLocal(iso: string) {
155	  const [y, m, d] = iso.split('-').map(Number);
156	  return new Date(y, (m || 1) - 1, d || 1);
157	}
