  it('renders without crashing', async () => {
    // Import the module (fast — already compiled by Vitest transform phase)
    const { default: EventosTimeline } = await import('./EventosTimeline');
    // Freeze timers AFTER import so the 800ms scroll-into-view timer
    // never fires and React async act() does not keep waiting for it.
    vi.useFakeTimers();
    try {
      // Wrap in sync act() to render without waiting for async effects.
      act(() => {
        render(<EventosTimeline />);
      });
      expect(document.body).toBeTruthy();
    } finally {
      vi.useRealTimers();
    }
  }, 120000);
});

