describe('EventosTimeline — smoke render', () => {
  // Freeze timers before any render so the 800ms scroll-into-view timer and
  // any Supabase realtime subscription timers never fire.  Real timers are
  // restored in afterAll so they don't leak into other suites.
  beforeAll(() => {
    vi.useFakeTimers();
  });

  afterAll(() => {
    vi.useRealTimers();
  });

  // NON-async test — prevents React 18 from wrapping in async act() which
  // would wait indefinitely for pending async effects to settle.
  it('renders without crashing', () => {
    // EventosTimelineDefault is the statically-imported component (top of file).
    // Static import is resolved before this test runs, so no cold-compile delay.
    act(() => {
      render(<EventosTimelineDefault />);
    });
    expect(document.body).toBeTruthy();
  }, 30000);
});

