29	/**
30	 * Faz parse seguro de uma string ou Date, tratando `"YYYY-MM-DD"` como **data local**
31	 * (evita deslocamento de fuso ao usar `new Date("2024-01-15")`).
32	 *
33	 * @param input - String ISO ou instância de Date.
34	 * @returns Date no fuso local (ou `Invalid Date` se `input` for inválido).
35	 *
36	 * @internal Usado pelas funções de formatação deste módulo.
37	 */
38	function parseAsLocalDate(input: string | Date): Date {
39	  if (input instanceof Date) return input;
40	  if (!input) return new Date(NaN);
41	  const isoLocalMatch = input.match(/^(\d{4})-(\d{2})-(\d{2})$/);
42	  if (isoLocalMatch) {
43	    const [, y, m, d] = isoLocalMatch;
44	    return new Date(Number(y), Number(m) - 1, Number(d));
45	  }
46	  return new Date(input);
47	}
