51	 *
52	 * @param title - Texto que pode conter uma data (ex.: `"Produção 15/02/25"`).
53	 * @returns String ISO `"YYYY-MM-DD"` ou `null` se não encontrado.
54	 *
55	 * @example
56	 * ```ts
57	 * parseDateFromTitle("Produção 15/02/25"); // "2025-02-15"
58	 * parseDateFromTitle("Sem data aqui");     // null
59	 * ```
60	 */
61	export function parseDateFromTitle(title: string): string | null {
62	  if (!title) return null;
63	  const m = title.match(/(\d{2})[/-](\d{2})[/-](\d{2,4})/);
64	  if (!m) return null;
65	  const dd = m[1];
66	  const mm = m[2];
67	  const yy = m[3];
68	  const year = yy.length === 2 ? `20${yy}` : yy;
69	  return `${year}-${mm}-${dd}`;
70	}
