91	 * @returns String `"YYYY-MM-DD"` ou string vazia se inválido.
92	 */
93	export function coerceISODateString(input: string | Date): string {
94	  if (typeof input === 'string') {
95	    const isoLocalMatch = input.match(/^(\d{4})-(\d{2})-(\d{2})$/);
96	    if (isoLocalMatch) return input;
97	  }
98	  const d = parseAsLocalDate(input);
99	  if (Number.isNaN(d.getTime())) return '';
100	  const dd = String(d.getDate()).padStart(2, '0');
101	  const mm = String(d.getMonth() + 1).padStart(2, '0');
102	  const yyyy = d.getFullYear();
103	  return `${yyyy}-${mm}-${dd}`;
104	}
