describe('EventosTimeline — smoke render', () => {
  // EventosTimeline is loaded dynamically to keep it isolated from the module
  // init phase. We load it in beforeAll (async-safe, outside test act context)
  // and keep a reference for the sync test body below.
  let EventosTimeline: React.ComponentType;

  // Disable React 18 async act() environment so createRoot.render() does NOT
  // flush effects synchronously and hang waiting for async Supabase queries.
  // Freeze timers so the 800ms scroll-into-view setTimeout never fires.
  beforeAll(async () => {
    (globalThis as any).IS_REACT_ACT_ENVIRONMENT = false;
    vi.useFakeTimers();
    const mod = await import('./EventosTimeline');
    EventosTimeline = mod.default;
  });

  afterAll(() => {
    (globalThis as any).IS_REACT_ACT_ENVIRONMENT = true;
    vi.useRealTimers();
  });

  it('renders without crashing', () => {
    // Use ReactDOM.createRoot directly to bypass @testing-library/react's
    // act() wrapping which hangs when async effects never fully settle.
    const container = document.createElement('div');
    document.body.appendChild(container);
    const root = createRoot(container);
    root.render(React.createElement(EventosTimeline));
    expect(container).toBeTruthy();
    root.unmount();
    document.body.removeChild(container);
  }, 10000);
});

