 2	 * Gera UUID v4 com fallback para contextos HTTP não-seguros (dev local, LAN).
 3	 *
 4	 * Usa `crypto.randomUUID()` quando disponível (HTTPS / Node 19+).
 5	 * Caso contrário, gera UUID v4 via Math.random (RFC 4122 compliant em formato).
 6	 */
 7	export function generateId(): string {
 8	  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
 9	    return crypto.randomUUID();
10	  }
11	  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
12	    const r = (Math.random() * 16) | 0;
13	    return (c === 'x' ? r : (r & 0x3) | 0x8).toString(16);
14	  });
15	}

